[InitializeOnLoad]public static class AnimationVisualQaDriver{
 const string Scene="Assets/Elemental/Content/Scenes/EarthCoreSlice.unity",Key="Elemental.AnimationVisualQa.Armed";
 static readonly List<A> a=new();static readonly List<Object> made=new();static readonly Dictionary<Behaviour,bool> off=new();
 static S s;static double at,limit,frameUntil;static bool run,pending,clockHeld,cameraFramingAdjusted;static float savedScale,savedTrackingHeight,savedNeutralPitch;static EarthCinemachineCameraController cameraController;static FieldInfo trackingHeightField,neutralPitchField;
 static AnimationVisualQaDriver(){EditorApplication.playModeStateChanged-=Play;EditorApplication.playModeStateChanged+=Play;}
 [MenuItem("Elemental/QA/Capture Final Animation Actual Game Matrix")]public static void Run(){if(run||SessionState.GetBool(Key,false))throw new Exception("Already running");if(SceneManager.GetActiveScene().path!=Scene)throw new Exception("Open EarthCoreSlice");SessionState.SetBool(Key,true);if(Application.isPlaying)Start();else EditorApplication.isPlaying=true;}
